/// Locks the scroll to the bottom (`true`) or unlocks it (`false`).
pub type SetLock = Rc<dyn Fn(bool, &mut Window, &mut App)>;

/// `content`, which scrolls with `handle`, beside its scroll column. With
    let track = canvas(
        // Where on the thumb it was grabbed, while it is being dragged. Kept
        // with the track from frame to frame, since each mouse move redraws
        // the column.
        |_, window, cx| {
            window.use_keyed_state("scroll-grab", cx, |_, _| Rc::new(Cell::new(None::<Pixels>)))
        },
        {
            let handle = handle.clone();
            let follow = follow.clone();
            move |bounds, grab: Entity<Rc<Cell<Option<Pixels>>>>, window, cx| {
                let grab = grab.read(cx).clone();
                let geometry = Geometry::of(&handle, bounds);
                // The track, with no background of its own: only the line
                // beside the list.
                window.paint_quad(fill(
                    Bounds::new(bounds.origin, size(px(1.), bounds.size.height)),
                    border,
                ));
                // The thumb fills the track's width, square: only a little
                // apart from the track, with lines across its top and bottom
                // that stand out more. Its sides are the column's own line and
                // edge, and at either end of the track the button's line is
                // its end, so none of its lines doubles another.
                let thumb = Bounds::new(
                    point(bounds.origin.x, geometry.thumb_top),
                    size(bounds.size.width, geometry.thumb_height),
                );
                let at_top = thumb.top() <= bounds.top() + px(0.5);
                let at_bottom = thumb.bottom() >= bounds.bottom() - px(0.5);
                window.paint_quad(quad(
                    thumb,
                    px(0.),
                    thumb_color,
                    Edges {
                        top: if at_top { px(0.) } else { px(1.) },
                        bottom: if at_bottom { px(0.) } else { px(1.) },
                        left: px(0.),
                        right: px(0.),
                    },
                    thumb_border,
                    BorderStyle::Solid,
                ));

                window.on_mouse_event({
                    let (handle, grab, follow) = (handle.clone(), grab.clone(), follow.clone());
                    move |event: &MouseDownEvent, phase, window, cx| {
                        if phase != DispatchPhase::Bubble || !bounds.contains(&event.position) {
                            return;
                        }
                        let geometry = Geometry::of(&handle, bounds);

